    int* data_;
    size_t size_;
public:
    Buffer& operator=(Buffer&& other) noexcept {
        // Exchange our members with other's
        // This avoids double-free and is exception-safe
        data_ = std::exchange(other.data_, nullptr);
        size_ = std::exchange(other.size_, 0);
        return *this;
    }
    ~Buffer() { delete[] data_; }
};

