// Practical: custom small vector with inline storage:
template<typename T, size_t N>
class StaticVector {
    alignas(T) char data_[sizeof(T) * N];
    size_t size_ = 0;
public:
    template<typename... Args>
    T& emplace_back(Args&&... args) {
        T* ptr = new (data_ + sizeof(T) * size_) T(std::forward<Args>(args)...);
        ++size_;
        return *ptr;
    }

    ~StaticVector() {
        for (size_t i = 0; i < size_; ++i) {
            reinterpret_cast<T*>(data_ + sizeof(T) * i)->~T();
        }
    }

    T& operator[](size_t i) {
        return *reinterpret_cast<T*>(data_ + sizeof(T) * i);
    }
};

